const root=document.querySelector('#experience'),key='kontur-amogus-campaign-v1';let cleanup=()=>{},screen='home',adminSession=false,adminStage=0,adminDialog=null,liveMission=null;let progress={stage:0,completed:false,free:false,questWins:0,motion:true,difficulty:'junior'};try{Object.assign(progress,JSON.parse(localStorage.getItem(key)||'{}'));}catch{}
const save=()=>{try{localStorage.setItem(key,JSON.stringify(progress));}catch{}};const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function reset(){audio.alarm(false);liveMission=null;cleanup();cleanup=()=>{};window.scrollTo(0,0);audio.transition();}
function shell(body,back=null){reset();root.innerHTML=`<div class="game-shell"><header class="global-header"><button class="wordmark" id="home"><span>К</span> ЦЕНТР ИНВЕСТ БАНК <small>IT LAB / AMOGUS</small></button><div><span class="local-tag">ЛОКАЛЬНАЯ ИГРА</span><button class="icon-button" id="sound" aria-label="Включить или выключить музыку">${audio.settings.enabled?'♫':'♩'}</button><button id="admin-open">Админка</button><button id="settings">Настройки</button>${back?'<button id="back">← Назад</button>':''}</div></header>${adminSession?'<div class="admin-session-bar"><span>ДЕМО / ОСНОВНОЕ СОХРАНЕНИЕ НЕ МЕНЯЕТСЯ</span><button id="leave-admin">Вернуться к своей игре</button><button id="admin-change">Выбрать другой момент · F2</button></div>':''}${body}<footer class="global-footer"><span>Сеть. Защита. Разработка. Одна история.</span><span>Все деньги и торги — игровые</span></footer></div>`;document.body.classList.toggle('reduce-motion',!progress.motion);document.querySelector('#home').onclick=()=>{adminSession=false;home();};document.querySelector('#admin-open').onclick=openAdmin;if(adminSession){document.querySelector('#leave-admin').onclick=()=>{adminSession=false;home();};document.querySelector('#admin-change').onclick=openAdmin;}document.querySelector('#sound').onclick=()=>{audio.start();audio.set(!audio.settings.enabled);document.querySelector('#sound').textContent=audio.settings.enabled?'♫':'♩';};document.querySelector('#settings').onclick=settings;if(back)document.querySelector('#back').onclick=back;}
function settings(){const host=document.querySelector('#mission'),prior=host?.dataset.paused;if(host)host.dataset.paused='true';const d=document.createElement('dialog');d.className='settings-dialog';d.innerHTML=`<form method="dialog"><button class="modal-close" aria-label="Закрыть настройки">×</button><span class="eyebrow">ЦЕНТР ИНВЕСТ БАНК / НАСТРОЙКИ</span><h2>Звук и изображение.</h2><label class="setting-row">Музыка<input type="checkbox" id="music-setting" ${audio.settings.enabled?'checked':''}></label><label class="setting-row">Громкость<input type="range" id="volume-setting" min="0" max="1" step=".01" value="${audio.settings.volume}"></label><label class="setting-row">Анимации и эффект телевизора<input type="checkbox" id="motion-setting" ${progress.motion?'checked':''}></label><label class="setting-row">Свободный доступ к режимам для показа<input type="checkbox" id="free-setting" ${progress.free?'checked':''}></label><p>Клавиша D перелистывает реплики сюжета. В 3D: WASD, E, Shift и Esc. Музыка начинается после первого нажатия.</p><button class="solid-button">Готово</button></form>`;document.body.append(d);d.querySelector('#music-setting').onchange=e=>{audio.start();audio.set(e.target.checked);};d.querySelector('#volume-setting').oninput=e=>audio.set(audio.settings.enabled,+e.target.value);d.querySelector('#motion-setting').onchange=e=>{progress.motion=e.target.checked;document.body.classList.toggle('reduce-motion',!progress.motion);save();};d.querySelector('#free-setting').onchange=e=>{progress.free=e.target.checked;save();};d.addEventListener('close',()=>{if(host){if(prior===undefined)delete host.dataset.paused;else host.dataset.paused=prior;}d.remove();if(screen==='home')home();});d.showModal();}
function home(){screen='home';audio.theme('menu');const unlocked=progress.completed||progress.free||adminSession;shell(`<main class="incident-home"><div class="home-grain"></div><div class="home-copy"><span class="eyebrow">ИНТЕРАКТИВНАЯ ИСТОРИЯ ОБ IT</span><h1>Когда всё<br>пошло <em>не так.</em></h1><p>Группировка AMOGUS вывела сеть из строя.<br>За одну ночь ты станешь сисадмином,<br>белым хакером и разработчиком.</p><button class="solid-button home-start">${progress.stage>0&&!progress.completed?'Продолжить историю':'Начать историю'} <span>↗</span></button><div class="home-modes"><button id="tycoon-mode" ${unlocked?'':'disabled'}>Тайкон <small>${unlocked?'Своя IT-компания':'После сюжета'}</small></button><button id="quest-mode" ${unlocked?'':'disabled'}>Квесты <small>${unlocked?'Три специальности':'После сюжета'}</small></button></div><span class="home-meta">БЕЗ КОДА · ПОНЯТНО С ПЕРВОЙ МИНУТЫ · 2D + 3D</span></div><div class="home-art"><div class="signal-rings"></div><div class="home-tower"><i></i><i></i><i></i><i></i><b>AMOGUS</b></div><div class="small-crt"><span>NO SIGNAL</span><i></i></div><span class="home-coordinate">23:47 / КОМНАТА УПРАВЛЕНИЯ</span></div></main>`);document.querySelector('.home-start').onclick=()=>{audio.start('story');if(progress.completed){progress.stage=0;save();}difficultyScreen();};document.querySelector('#tycoon-mode').onclick=tycoon;document.querySelector('#quest-mode').onclick=quests;}
function difficultyScreen(){screen='difficulty';audio.theme('menu');shell(`<main class="access-screen"><div class="access-art"><canvas id="binary-mask" aria-label="Маска из нулей и единиц на фоне цифрового дождя"></canvas><span class="access-signal"><i></i> ЗАЩИЩЁННЫЙ КАНАЛ / 00:01</span></div><section class="access-content"><span class="eyebrow">ПРОТОКОЛ ДОСТУПА / СЮЖЕТНАЯ КАМПАНИЯ</span><h1>Время —<br>твой <em>ресурс.</em></h1><p class="access-lead">Одна ночь. Три профессии. Выбери, сколько времени у тебя будет на спасение системы.</p><div class="difficulty-options" role="group" aria-label="Сложность сюжета">${Object.entries(DIFFICULTIES).map(([id,d],i)=>`<button class="difficulty-card" data-difficulty="${id}" aria-pressed="${id===progress.difficulty}"><span class="difficulty-index">0${i+1}</span><span><strong>${d.name}</strong><small>${d.tag}</small></span><i>${'▮'.repeat(i+1)}</i></button>`).join('')}</div><div class="difficulty-summary" aria-live="polite"></div><button class="solid-button access-start">${progress.stage>0&&!progress.completed?'Продолжить сюжет':'Войти в историю'} <span>↗</span></button><p class="difficulty-note">Сложность меняет только таймеры сюжета. Тайкон и отдельные квесты остаются прежними.</p><button class="access-menu">В главное меню →</button></section></main>`,home);let selected=DIFFICULTIES[progress.difficulty]?progress.difficulty:'junior';const summary=document.querySelector('.difficulty-summary');function update(){const d=difficultyFor(selected);document.querySelectorAll('[data-difficulty]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.difficulty===selected)));summary.innerHTML=`<p>${d.description}</p><div>${[['sysadmin','Серверная · кабель, SSD, RAM'],['security','Защита от атаки'],['frontend','Исправление системы']].map(([id,label])=>`<span><small>${label}</small><b>${clockTime(d.times[id])}</b></span>`).join('')}</div>`;}document.querySelectorAll('[data-difficulty]').forEach(b=>b.onclick=()=>{selected=b.dataset.difficulty;update();});update();document.querySelector('.access-start').onclick=()=>{progress.difficulty=selected;if(progress.completed)progress.stage=0;save();audio.start('story');resumeStory();};document.querySelector('.access-menu').onclick=home;cleanup=mountBinaryMask(document.querySelector('#binary-mask'),{motion:progress.motion});}
function tv(lines,next,{startAt=0}={}){lines=lines.map(([label,text])=>[label.startsWith('СИСАДМИН /')?'СИСАДМИН / '+clockTime(storyTime(progress.difficulty,'sysadmin')):label.startsWith('БЕЛЫЙ ХАКЕР /')?'БЕЛЫЙ ХАКЕР / '+clockTime(storyTime(progress.difficulty,'security')):label,label.startsWith('СИСАДМИН /')?'Восстанови кабель, перезапусти серверы и установи SSD с оперативной памятью. Подсветка покажет путь.':text]);screen='story';audio.theme('story');shell(`<main class="tv-scene"><div class="tv-ambient"></div><div class="tv-cabinet"><div class="tv-front"><div class="tv-screen"><div class="tv-noise"></div><div class="tv-scan"></div><span class="tv-caption"></span><p class="tv-phrase"></p><span class="tv-dots">...</span><div class="amogus-mark"><i></i><b>A</b></div></div><div class="tv-controls"><i></i><i></i><span>ЦЕНТР ИНВЕСТ БАНК<br>ЭЛТ / 1987</span><div></div></div></div><div class="tv-feet"></div></div><div class="tv-floor"></div><div class="story-bottom"><span class="story-count"></span><button class="story-next">D <small>следующая реплика</small> →</button></div></main>`,home);let index=Math.max(0,Math.min(lines.length-1,startAt)),elapsed=0,last=performance.now(),raf,disposed=false;const phrase=document.querySelector('.tv-phrase'),caption=document.querySelector('.tv-caption');function show(){elapsed=0;caption.textContent=lines[index][0];phrase.textContent='';document.querySelector('.tv-dots').style.opacity=0;document.querySelector('.story-count').textContent=String(index+1).padStart(2,'0')+' / '+String(lines.length).padStart(2,'0');document.querySelector('.amogus-mark').classList.toggle('show',lines[index][0].includes('AMOGUS')||lines[index][0].includes('ПЕРЕХВАТ'));}function advance(){if(disposed)return;index++;audio.transition();if(index===lines.length){next();return;}show();}function kd(e){if(e.code==='KeyD'&&!e.repeat&&!document.querySelector('dialog[open]')){e.preventDefault();advance();}}document.querySelector('.story-next').onclick=advance;window.addEventListener('keydown',kd);function draw(now){if(disposed)return;raf=requestAnimationFrame(draw);const dt=(now-last)/1000;last=now;if(document.hidden||document.querySelector('dialog[open]'))return;elapsed+=Math.min(.1,dt);const text=lines[index][1],typed=progress.motion?Math.floor(elapsed/.032):text.length;const visible=text.slice(0,typed);if(phrase.textContent!==visible)phrase.textContent=visible;const ready=typed>=text.length;document.querySelector('.tv-dots').style.opacity=ready?1:0;const readTime=Math.max(3,text.split(/\s+/).length/2.8);if(elapsed>text.length*.032+readTime+1)advance();}show();raf=requestAnimationFrame(draw);cleanup=()=>{disposed=true;cancelAnimationFrame(raf);window.removeEventListener('keydown',kd);};}
function resumeStory(){const stage=adminSession?adminStage:progress.stage;if(stage===0)tv(STORY.opening,()=>mission('sysadmin',true));else if(stage===1)tv(STORY.second,()=>mission('security',true));else if(stage===2)tv(STORY.developer,()=>mission('frontend',true));else tv(STORY.ending,modeChoice);}
const META={sysadmin:['Сисадмин','Вернуть связь до обрыва',120],security:['Белый хакер','Отразить вторую волну',60],frontend:['Разработчик','Закрыть уязвимости',180],audit:['Белый хакер','Тихое проникновение',120]};
function mission(id,story=false,options={}){screen='mission';audio.theme('crisis');const [name,title,baseLimit]=META[id],limit=story?(storyTime(progress.difficulty,id)||baseLimit):id==='sysadmin'?360:baseLimit;shell(`<main class="mission-page"><div class="mission-heading"><div><span class="eyebrow">${story?'СЮЖЕТ / '+difficultyFor(progress.difficulty).name.toUpperCase():'КВЕСТ ПО СПЕЦИАЛЬНОСТИ'} · ${name.toUpperCase()}</span><h1>${options.checkpoint&&id==='sysadmin'?(SERVER_CHECKPOINTS.find(c=>c[0]===options.checkpoint)?.[1]||title):title}</h1></div><div class="mission-timer"><small>ОСТАЛОСЬ</small><b>${clockTime(limit)}</b></div></div><div id="mission"></div><div id="mission-outcome"></div></main>`,story?home:quests);if(id==='sysadmin'){audio.start('crisis');audio.alarm(true);}const host=document.querySelector('#mission');let completed=false,remaining=limit,last=performance.now(),disposed=false,raf;const onDone=()=>{if(completed)return;completed=true;audio.alarm(false);audio.success();if(story&&adminSession){adminStage=({sysadmin:1,security:2,frontend:3})[id];}else if(story){progress.stage=Math.max(progress.stage,({sysadmin:1,security:2,frontend:3})[id]);if(progress.stage===3)progress.completed=true;}else if(!adminSession)progress.questWins++;if(!adminSession)save();document.querySelector('#mission-outcome').innerHTML=`<div class="outcome"><div><span class="eyebrow">${story?'ВОЛНА ПРОЙДЕНА':'КВЕСТ ЗАВЕРШЁН'}</span><h2>${story?'Связь с командой восстановлена.':'Практика — в копилку.'}</h2></div><button class="solid-button" id="mission-next">${story?'Продолжить историю →':'К специальностям →'}</button></div>`;document.querySelector('#mission-next').onclick=story?resumeStory:quests;};let disposeGame=id==='sysadmin'?mountServerRoom(host,onDone,{scope:'full',checkpoint:options.checkpoint||null}):id==='security'?mountDdos(host,onDone,{startWave:options.startWave||0}):id==='audit'?mountNetwork(host,onDone):mountDeveloper(host,onDone,{incident:story,checkpoint:options.checkpoint||'start'});if(!story&&id==='sysadmin')remaining=360;const timerLabel=document.querySelector('.mission-timer');if(options.timer===false){timerLabel.querySelector('small').textContent='БЕЗ ТАЙМЕРА';timerLabel.querySelector('b').textContent='∞';}
 function fail(){audio.alarm(false);disposeGame();host.innerHTML='<div class="failure"><span>СВЯЗЬ ПОТЕРЯНА</span><h2>Попробуем ещё раз.</h2><p>Не хватило времени. Пройденные этапы истории сохранены.</p><button class="solid-button" id="retry-mission">Повторить миссию →</button></div>';document.querySelector('#retry-mission').onclick=()=>mission(id,story,options);completed=true;}
 function draw(now){if(disposed)return;raf=requestAnimationFrame(draw);const dt=Math.min(.1,(now-last)/1000);last=now;if(completed||liveMission?.frozen||document.hidden||document.querySelector('dialog[open]')||host.dataset.paused==='true')return;remaining=Math.max(0,remaining-dt);const b=document.querySelector('.mission-timer b');b.textContent=Math.floor(Math.ceil(remaining)/60)+':'+String(Math.ceil(remaining)%60).padStart(2,'0');b.classList.toggle('urgent',remaining<20);if(remaining===0)fail();}liveMission={win:onDone,fail,addTime:()=>remaining+=60,frozen:options.timer===false};raf=requestAnimationFrame(draw);cleanup=()=>{disposed=true;cancelAnimationFrame(raf);disposeGame();};}
function modeChoice(){screen='modes';if(!adminSession){progress.completed=true;save();}audio.theme('menu');shell(`<main class="mode-choice"><span class="eyebrow">AMOGUS / ГЛАВА ЗАВЕРШЕНА</span><h1>Ночь закончилась.<br><em>Твоя история — нет.</em></h1><p>Теперь ты знаешь, как сеть, защита и разработка зависят друг от друга.</p><div><button class="mode-card" id="choose-tycoon"><span>01 / КОМПАНИЯ</span><h2>Тайкон</h2><p>Люди, оборудование, кейсы, торговля и клановые войны.</p><b>Открыть компанию ↗</b></button><button class="mode-card" id="choose-quests"><span>02 / ПРАКТИКА</span><h2>Квесты</h2><p>Три специальности. Новые попытки. Больше опыта.</p><b>Выбрать специальность ↗</b></button></div></main>`,home);document.querySelector('#choose-tycoon').onclick=tycoon;document.querySelector('#choose-quests').onclick=quests;}
function professionRoom(mode='quests'){screen='quests';audio.theme('menu');shell(`<main class="campus profession-campus"><img class="campus-bg" src="assets/classroom.png" alt="Учебная аудитория"><canvas id="campus3d" aria-label="Класс с доской Центр Инвест Банк"></canvas><div class="campus-shade"></div><div class="campus-title"><span class="eyebrow">ЦЕНТР ИНВЕСТ БАНК / IT ЛАБОРАТОРИЯ</span><h1>Твоё место.<br><em>Твой профиль.</em></h1><p>${mode==='tycoon'?'Выбери профессию компании: у каждой свой интерфейс и преимущества.':'Выбери рабочее место и войди в практику.'}</p></div><div class="profession-stations">${Object.entries(PROFESSIONS).map(([id,r],i)=>`<button data-profession="${id}" style="--role:${r.accent}"><span>0${i+1} / ${mode==='tycoon'?'КОМПАНИЯ':'ПРАКТИКА'}</span><i>${['⌘','◇','⌁'][i]}</i><h2>${r.name}</h2><p>${mode==='tycoon'?r.bonus:id==='frontend'?'Останови сбой банковской сети: изолируй, исправь, проверь, выпусти.':id==='security'?'Отдели атаку от обычных посетителей.':'Три комнаты: кабель, перезапуск, SSD и RAM.'}</p><b>Занять рабочее место ↗</b></button>`).join('')}</div></main>`,home);const campus=createCampus(document.querySelector('#campus3d'));cleanup=()=>campus.dispose();document.querySelectorAll('[data-profession]').forEach(b=>b.onclick=()=>{const id=b.dataset.profession;if(mode==='tycoon')tycoon({profession:id});else mission(id);});}
function quests(){professionRoom('quests');}
function tycoon(options={}){if(!options.profession&&!options.initialState){professionRoom('tycoon');return;}screen='tycoon';audio.theme('menu');shell('<main id="tycoon-root"></main>',home);cleanup=mountTycoon(document.querySelector('#tycoon-root'),{onQuest:quests,audio,profession:options.profession,sandbox:adminSession,initialState:options.initialState||(adminSession?adminCompany(options):null),startView:options.startView||'office',openAt:options.openAt||null});}

function openAdmin(){if(adminDialog?.open){adminDialog.close();return;}const host=document.querySelector('#mission'),prior=host?.dataset.paused;if(host)host.dataset.paused='true';document.exitPointerLock?.();adminDialog=showAdmin({hasMission:!!liveMission,onClose:()=>{if(host){if(prior===undefined)delete host.dataset.paused;else host.dataset.paused=prior;}adminDialog=null;},onMissionAction:command=>{adminSession=true;if(!liveMission)return;if(command==='win')liveMission.win();if(command==='fail')liveMission.fail();if(command==='time')liveMission.addTime();if(command==='freeze'){liveMission.frozen=!liveMission.frozen;document.querySelector('.mission-timer small').textContent=liveMission.frozen?'БЕЗ ТАЙМЕРА':'ОСТАЛОСЬ';if(liveMission.frozen)document.querySelector('.mission-timer b').textContent='∞';}},onGo:(id,options)=>{adminSession=true;audio.start();const [kind,stage,line]=id.split(':');if(kind==='tv'){const mapping={opening:0,second:1,developer:2,ending:3};adminStage=mapping[stage];tv(STORY[stage],()=>stage==='ending'?modeChoice():mission(stage==='opening'?'sysadmin':stage==='second'?'security':'frontend',true,{timer:options.timer}),{startAt:+line});}else if(kind==='server')mission('sysadmin',false,{checkpoint:stage,timer:options.timer});else if(kind==='defense')mission('security',false,{startWave:+stage,timer:options.timer});else if(kind==='developer')mission('frontend',false,{checkpoint:stage,timer:options.timer});else if(kind==='audit')mission('audit',false,{timer:options.timer});else if(kind==='tycoon')tycoon({...options,initialState:preparedCompany(stage,options),startView:['walk','install-ssd','install-ram'].includes(stage)?'office':({'hardware':'office','loot':'stock','case-running':'cases','case-finish':'cases','own-order':'market','position-close':'futures','auction-bid':'zozon','auction-finish':'zozon','war-running':'clans'})[stage]||stage,openAt:stage==='walk'?'walk':stage==='install-ssd'?'ssd':stage==='install-ram'?'ram':null});else if(kind==='classroom')professionRoom('tycoon');else if(kind==='modes')modeChoice();else quests();}});}
window.addEventListener('keydown',e=>{if(e.code==='F2'){e.preventDefault();openAdmin();}});
difficultyScreen();window.addEventListener('pagehide',()=>{save();cleanup();});if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
